import os
from mindee import MindeeClient
from mindee.product import Invoice

def validate_invoice_fields(document_path: str, confidence_threshold: float = 0.8) -> dict:
    api_key = os.getenv("MINDEE_API_KEY")
    if not api_key:
        raise ValueError("MINDEE_API_KEY environment variable is not set")
    client = MindeeClient(api_key=api_key)
    result = client.load_document(document_path).parse(Invoice)
    if not result.document.inference.pages:
        raise ValueError("No document pages found")
    prediction = result.document.inference.pages[0].prediction
    required_fields = {
        "supplier_name": prediction.supplier.name if prediction.supplier else None,
        "invoice_number": prediction.invoice_number,
        "invoice_date": prediction.invoice_date,
        "due_date": prediction.due_date,
        "total_incl": prediction.total_incl,
    }
    validated = {}
    for field_name, field in required_fields.items():
        if field is None or field.confidence < confidence_threshold:
            conf = field.confidence if field else 0.0
            raise ValueError(
                f"Required field '{field_name}' is missing or has low confidence: {conf:.2f} < {confidence_threshold}"
            )
        validated[field_name] = field.value
    return validated
